var root=UnityEditor.PrefabUtility.LoadPrefabContents("Assets/Prefabs/Character.prefab");
try{
 var rig=root.GetComponent<Character.Control.PaddleCharacterVisual>();var indices=new System.Collections.Generic.HashSet<int>();float scaleError=0,drift=0,maxApprox=0;
 UnityEngine.Vector3 localL=UnityEngine.Vector3.zero,localR=UnityEngine.Vector3.zero;
 for(int i=0;i<1440;i++){
  float radius=new[]{.75f,1.05f,1.5f,1.975f}[i/360];var q=UnityEngine.Quaternion.Euler(0,0,i%360);rig.tool.rotation=q;rig.tool.position=rig.body.position+q*new UnityEngine.Vector3(radius,.074f,0);rig.Pose();
  indices.Add(rig.LeftPose);indices.Add(rig.RightPose);maxApprox=UnityEngine.Mathf.Max(maxApprox,rig.HandError);
  var l=rig.paddle.transform.InverseTransformPoint(rig.LeftHand);var r=rig.paddle.transform.InverseTransformPoint(rig.RightHand);if(i==0){localL=l;localR=r;}else drift=UnityEngine.Mathf.Max(drift,UnityEngine.Vector3.Distance(l,localL),UnityEngine.Vector3.Distance(r,localR));
  foreach(var sr in root.GetComponentsInChildren<UnityEngine.SpriteRenderer>())if(sr.name.StartsWith("Remake ")){scaleError=UnityEngine.Mathf.Max(scaleError,UnityEngine.Mathf.Abs(sr.transform.localScale.x-1));if(sr.sprite.rect.width!=320||sr.sprite.rect.height!=320||sr.sprite.pivot!=new UnityEngine.Vector2(160,280))throw new System.Exception("Frame canvas/pivot mismatch");}
 }
 string log="1440 poses: selected="+string.Join(",",indices.OrderBy(x=>x))+"; constant scale error="+scaleError+" fixed target drift="+drift+" max pose endpoint approximation="+maxApprox;
 System.IO.File.WriteAllText("scripts/player-frame-arms-20261111/frame-check.txt",log);UnityEngine.Debug.Log(log);
 if(indices.Count!=8||scaleError>.00001f||drift>.00001f)throw new System.Exception("Frame selection regression");
}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}
